struct tuning {
	// A is N x N, row-major: inner dim 'j', outer dim 'i'
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// 1D vectors indexed primarily by 'i'
	DEFINE_PROTO_STRUCT(u_layout, i_vec);

