void kernel_gemver(num_t alpha, num_t beta,
                   auto A, auto u1, auto v1, auto u2, auto v2,
                   auto w, auto x, auto y, auto z) {
	using namespace noarr;

	#pragma scop

	// --------------------------------------------------------------------
	// 1) A[i][j] = A[i][j] + u1[i]*v1[j] + u2[i]*v2[j];
	//
	// We keep the row-major traversal (i outer, j inner), but we hoist
	// u1[i] and u2[i] out of the inner j-loop so they are loaded once
	// per row. The compiler is likely able to discover this, but doing
	// it explicitly makes the intent clear and guarantees no redundant
	// loads from u1/u2.
	// --------------------------------------------------------------------
	traverser(A, u1, v1, u2, v2).template for_dims<'i'>([=](auto trav_i) {
