	// pattern into a row-wise streaming traversal of A.
	// --------------------------------------------------------------------
	auto y_i = y ^ noarr::rename<'j', 'i'>(); // y_i[i] == y[i]
	auto x_j = x ^ noarr::rename<'i', 'j'>(); // x_j[j] == x[j]

	traverser(A, x_j, y_i).template for_dims<'i'>([=](auto trav_i) {
		// Fix one matrix row: index in dimension 'i'
		auto state_i = trav_i.state();
		const num_t y_val = y_i[state_i]; // y for this row, reused for all cols

		// Now iterate over columns 'j' within that row
		trav_i.template for_each<'j'>([=](auto state) {
			// state: ('i' = row, 'j' = col)
			// A[state]  == A[row][col]
			// x_j[state] == x[col]
			x_j[state] = x_j[state] + beta * A[state] * y_val;
		});
	});

	// --------------------------------------------------------------------
	// 3) x[i] = x[i] + z[i];
	//
	// Simple vector update. We keep it separate from (2) to preserve the
	// original loop structure and avoid changing the order of FP
	// operations more than necessary (which would slightly change
	// rounding).
	// --------------------------------------------------------------------
	traverser(x, z).for_each([=](auto state) {
		x[state] = x[state] + z[state];
	});

	// --------------------------------------------------------------------
	// 4) w[i] = w[i] + alpha * A[i][j] * x[j];
	//
	// This is w = w + alpha * A * x.
	// A is row-major in 'i' x 'j' (rows x cols), and x is indexed by 'i'.
	// We want to access x using the column index 'j', so we reuse the
	// x_j view created above:
	//   x_j[j] == x[j]
	//
	// Traversal is row-major (i outer, j inner), which is already
	// cache-friendly for A.
	// --------------------------------------------------------------------
	traverser(A, w, x_j).template for_dims<'i'>([=](auto trav_i) {
		trav_i.template for_each<'j'>([=](auto state) {
			w[state] = w[state] + alpha * A[state] * x_j[state];
		});
	});

	#pragma endscop
